using System;using System.IO;using System.Reflection;using System.Text;using UnityEditor;using UnityEngine;using StarterAssets;
[InitializeOnLoad]public static class CheckCombatAudio {
 const string Req="Assets/Editor/CQC/CheckCombatAudio.request.txt",Report="C:/Users/Joshua/Documents/Codex/2026-10-11/ca/outputs/combat-sfx-check.txt";const BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;
 static CheckCombatAudio(){EditorApplication.update+=Poll;}
 static void Poll(){if(!File.Exists(Req)||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete(Req);try{Run();}catch(Exception e){File.WriteAllText(Report,e.ToString());Debug.LogException(e);}}
 static void Call(object target,string method)=>target.GetType().GetMethod(method,Private).Invoke(target,null);
 public static void Run(){var report=new StringBuilder();foreach(var guid in AssetDatabase.FindAssets("t:AudioClip",new[]{"Assets/Resources/CombatAudio"})){var path=AssetDatabase.GUIDToAssetPath(guid);var im=(AudioImporter)AssetImporter.GetAtPath(path);im.forceToMono=true;var sample=im.defaultSampleSettings;sample.loadType=AudioClipLoadType.DecompressOnLoad;im.defaultSampleSettings=sample;im.SaveAndReimport();var clip=AssetDatabase.LoadAssetAtPath<AudioClip>(path);if(!clip||clip.length<=0||clip.length>5)throw new Exception("Invalid or untrimmed cue: "+path);report.AppendLine(clip.name+": "+clip.length.ToString("F2")+"s imported");}
 var go=new GameObject("Temporary combat audio check");try{var weapon=go.AddComponent<WeaponController>();foreach(var type in new[]{WeaponController.Weapon.Sword,WeaponController.Weapon.Greatsword}){weapon.CurrentWeapon=type;Call(weapon,"ResetSlashSoundWindow");Call(weapon,"ResolveSlashSound");var audio=go.GetComponent<CombatSoundEmitter>();if(audio.LastClip!=CombatSoundEmitter.SlashMiss)throw new Exception("Miss cue selection failed");int count=audio.PlayCount;Call(weapon,"ResolveSlashSound");if(audio.PlayCount!=count)throw new Exception("Sound repeated each frame");Call(weapon,"NoteSlashContact");Call(weapon,"ResolveSlashSound");if(audio.LastClip!=CombatSoundEmitter.SlashHit||audio.PlayCount!=count+1)throw new Exception("Hit cue selection failed");Call(weapon,"ResolveSlashSound");if(audio.PlayCount!=count+1)throw new Exception("Repeated contact duplicated impact sound");report.AppendLine(type+": miss/hit selection and per-strike deduplication passed");}
 foreach(bool cyclops in new[]{true,false}){typeof(CombatSoundEmitter).GetField("nextEnemyCue",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,-1f);var actor=new GameObject("Temporary enemy audio check");try{var emitter=actor.AddComponent<CombatSoundEmitter>();emitter.EnemyAttack(cyclops);if(!emitter.LastClip||(cyclops?!emitter.LastClip.name.StartsWith("CyclopsAttack"):emitter.LastClip!=CombatSoundEmitter.FlyingAttack))throw new Exception("Enemy audio selection failed");int count=emitter.PlayCount;emitter.EnemyAttack(cyclops);if(emitter.PlayCount!=count)throw new Exception("Enemy cue rate limiting failed");report.AppendLine((cyclops?"Cyclops":"Flying enemy")+": correct cue and repeat limiter passed");}finally{UnityEngine.Object.DestroyImmediate(actor);}}
 File.WriteAllText(Report,report.ToString());Debug.Log("COMBAT_AUDIO_PASSED\n"+report);
 }finally{UnityEngine.Object.DestroyImmediate(go);}}
}
